    // Dualkit utilities: Eastern to Western numeral normalisation
    function toWesternDigits(str) {
      if (!str) return '';
      const eastern = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
      const persian = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
      return str.split('').map(char => {
        const eIdx = eastern.indexOf(char);
        if (eIdx !== -1) return eIdx.toString();
        const pIdx = persian.indexOf(char);
        if (pIdx !== -1) return pIdx.toString();
        return char;
      }).join('');
    }

    // Phone normaliser & formatter (UAE local style)
    const phoneInput = document.getElementById('phone-input');
    phoneInput.addEventListener('input', (e) => {
      let val = toWesternDigits(e.target.value);
      // Remove all non-digits
      let digits = val.replace(/\D/g, '');
      // Strip leading trunk zero or country code if typed inside input
      if (digits.startsWith('971')) digits = digits.substring(3);
      if (digits.startsWith('0')) digits = digits.substring(1);

      // Limit to 9 digits (UAE mobiles are 9 digits without trunk zero: 50xxxxxxx)
      digits = digits.substring(0, 9);

      // Format as 50 123 4567
      let formatted = digits;
      if (digits.length > 2 && digits.length <= 5) {
        formatted = `${digits.slice(0, 2)} ${digits.slice(2)}`;
      } else if (digits.length > 5) {
        formatted = `${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5)}`;
      }
      e.target.value = formatted;
    });

    // Makani normaliser (10 digits formatted as 12345 67890)
